-- CP11 schema change demo, step 1: the stand-in CLD.
-- PUBLISHER plays the SAP side (the data product owner). MAINTENANCE plays the
-- catalog-linked database we read. SYNC_L0 copies PUBLISHER into MAINTENANCE every
-- minute, like a CLD sync: rows, added/dropped columns, dropped/recreated tables.
-- Idempotent: rerunning rebuilds L0 to the same baseline. MINING_360 is not touched.

create database if not exists {{DEMO_L0}} comment = 'CP11: stand-in for a SAP BDC catalog-linked database';
create database if not exists {{DEMO_DB}} comment = 'CP11: L1, L2, control and serving for the schema change demo';

create or replace schema {{DEMO_L0}}.PUBLISHER comment = 'SAP side: the data product as published. Scenarios change this schema.';
create or replace schema {{DEMO_L0}}.MAINTENANCE comment = 'CLD stand-in: what Snowflake sees after sync. Never edited by hand.';
create schema if not exists {{DEMO_L0}}.SYNC comment = 'Sync procedure, task and state';

-- Seed: 10 machines at two pits, 300 maintenance notifications Jul-Sep 2026 (deterministic)
create or replace table {{DEMO_L0}}.PUBLISHER.EQUIPMENT (
  EQUIPMENT varchar, EQUIPMENTNAME varchar, PLANT varchar, EQUIPMENTCATEGORY varchar, FLEETTYPE varchar);
insert into {{DEMO_L0}}.PUBLISHER.EQUIPMENT
select 'E-' || (1000 + n),
       case when n <= 7 then 'Haul truck ' || lpad(n, 2, '0') when n <= 9 then 'Shovel ' || lpad(n - 7, 2, '0') else 'Loader 01' end,
       iff(n <= 6, '1710', '1010'), 'M',
       case when n <= 7 then 'HAUL_TRUCK' when n <= 9 then 'SHOVEL' else 'LOADER' end
from (select row_number() over (order by seq4()) as n from table(generator(rowcount => 10)));

create or replace table {{DEMO_L0}}.PUBLISHER.MAINT_NOTIFICATION (
  MAINTENANCENOTIFICATION varchar, EQUIPMENT varchar, NOTIFICATIONTYPE varchar,
  PRIORITY varchar, CREATEDON date, DOWNTIMEHOURS number(10,2), NOTIFICATIONTEXT varchar);
insert into {{DEMO_L0}}.PUBLISHER.MAINT_NOTIFICATION
select 'N-' || lpad(n, 6, '0'),
       'E-' || (1001 + mod(n * 7, 10)),
       iff(mod(n, 3) = 0, 'M2', 'M1'),
       to_varchar(1 + mod(n, 4)),
       dateadd(day, mod(n * 13, 92), '2026-07-01'::date),
       (1 + mod(n * 37, 230) / 10)::number(10,2),
       iff(mod(n, 3) = 0, 'Breakdown - ', 'Planned service - ') || 'notification ' || n
from (select row_number() over (order by seq4()) as n from table(generator(rowcount => 300)));

-- Zero-copy baseline of the SAP side, used by 79_restore.sql
create or replace schema {{DEMO_L0}}.BASELINE clone {{DEMO_L0}}.PUBLISHER;

-- Sync state and log
create or replace table {{DEMO_L0}}.SYNC.L0_SYNC_STATE (LAST_SYNC_AT timestamp_ltz, LAST_ACTIONS varchar);
insert into {{DEMO_L0}}.SYNC.L0_SYNC_STATE values (null, null);
create or replace table {{DEMO_L0}}.SYNC.SYNC_LOG (SYNC_AT timestamp_ltz, ACTIONS varchar);

-- Column catalogue of both schemas with a type that can be replayed in DDL
create or replace view {{DEMO_L0}}.SYNC.V_COLS as
select c.TABLE_SCHEMA, c.TABLE_NAME, c.COLUMN_NAME, c.ORDINAL_POSITION,
       case c.DATA_TYPE when 'NUMBER' then 'NUMBER(' || c.NUMERIC_PRECISION || ',' || c.NUMERIC_SCALE || ')'
                        when 'TEXT' then 'VARCHAR' else c.DATA_TYPE end as TYPE_SQL
from {{DEMO_L0}}.INFORMATION_SCHEMA.COLUMNS c
join {{DEMO_L0}}.INFORMATION_SCHEMA.TABLES t
  on t.TABLE_SCHEMA = c.TABLE_SCHEMA and t.TABLE_NAME = c.TABLE_NAME and t.TABLE_TYPE = 'BASE TABLE'
where c.TABLE_SCHEMA in ('PUBLISHER', 'MAINTENANCE');

-- The sync. Rows are append-only (new rows in PUBLISHER are inserted); the scenarios never update rows.
create or replace procedure {{DEMO_L0}}.SYNC.SP_SYNC_L0()
returns varchar
language sql
execute as owner
as
$$
declare
  actions varchar default '';
  c_drop cursor for
    select distinct TABLE_NAME from {{DEMO_L0}}.SYNC.V_COLS where TABLE_SCHEMA = 'MAINTENANCE'
    minus select distinct TABLE_NAME from {{DEMO_L0}}.SYNC.V_COLS where TABLE_SCHEMA = 'PUBLISHER';
  c_new cursor for
    select distinct TABLE_NAME from {{DEMO_L0}}.SYNC.V_COLS where TABLE_SCHEMA = 'PUBLISHER'
    minus select distinct TABLE_NAME from {{DEMO_L0}}.SYNC.V_COLS where TABLE_SCHEMA = 'MAINTENANCE';
  c_type cursor for
    select distinct p.TABLE_NAME from {{DEMO_L0}}.SYNC.V_COLS p
    join {{DEMO_L0}}.SYNC.V_COLS m on m.TABLE_SCHEMA = 'MAINTENANCE' and m.TABLE_NAME = p.TABLE_NAME and m.COLUMN_NAME = p.COLUMN_NAME
    where p.TABLE_SCHEMA = 'PUBLISHER' and p.TYPE_SQL <> m.TYPE_SQL;
  c_add cursor for
    select p.TABLE_NAME, p.COLUMN_NAME, p.TYPE_SQL from {{DEMO_L0}}.SYNC.V_COLS p
    where p.TABLE_SCHEMA = 'PUBLISHER'
      and p.TABLE_NAME in (select TABLE_NAME from {{DEMO_L0}}.SYNC.V_COLS where TABLE_SCHEMA = 'MAINTENANCE')
      and not exists (select 1 from {{DEMO_L0}}.SYNC.V_COLS m where m.TABLE_SCHEMA = 'MAINTENANCE'
                      and m.TABLE_NAME = p.TABLE_NAME and m.COLUMN_NAME = p.COLUMN_NAME)
    order by p.TABLE_NAME, p.ORDINAL_POSITION;
  c_del cursor for
    select m.TABLE_NAME, m.COLUMN_NAME from {{DEMO_L0}}.SYNC.V_COLS m
    where m.TABLE_SCHEMA = 'MAINTENANCE'
      and m.TABLE_NAME in (select TABLE_NAME from {{DEMO_L0}}.SYNC.V_COLS where TABLE_SCHEMA = 'PUBLISHER')
      and not exists (select 1 from {{DEMO_L0}}.SYNC.V_COLS p where p.TABLE_SCHEMA = 'PUBLISHER'
                      and p.TABLE_NAME = m.TABLE_NAME and p.COLUMN_NAME = m.COLUMN_NAME);
  c_rows cursor for
    select TABLE_NAME, listagg('"' || COLUMN_NAME || '"', ', ') within group (order by ORDINAL_POSITION) as COLS
    from {{DEMO_L0}}.SYNC.V_COLS where TABLE_SCHEMA = 'MAINTENANCE' group by TABLE_NAME;
  stmt varchar;
  n number;
begin
  -- Table removed by the publisher
  for r in c_drop do
    stmt := 'drop table {{DEMO_L0}}.MAINTENANCE."' || r.TABLE_NAME || '"';
    execute immediate :stmt;
    actions := actions || 'TABLE_REMOVED ' || r.TABLE_NAME || '; ';
  end for;
  -- New table, or a table republished with a changed column type: take the published table as is
  for r in c_new do
    stmt := 'create table {{DEMO_L0}}.MAINTENANCE."' || r.TABLE_NAME || '" clone {{DEMO_L0}}.PUBLISHER."' || r.TABLE_NAME || '"';
    execute immediate :stmt;
    stmt := 'alter table {{DEMO_L0}}.MAINTENANCE."' || r.TABLE_NAME || '" set change_tracking = true';
    execute immediate :stmt;
    actions := actions || 'TABLE_ADDED ' || r.TABLE_NAME || '; ';
  end for;
  for r in c_type do
    stmt := 'create or replace table {{DEMO_L0}}.MAINTENANCE."' || r.TABLE_NAME || '" clone {{DEMO_L0}}.PUBLISHER."' || r.TABLE_NAME || '"';
    execute immediate :stmt;
    stmt := 'alter table {{DEMO_L0}}.MAINTENANCE."' || r.TABLE_NAME || '" set change_tracking = true';
    execute immediate :stmt;
    actions := actions || 'TABLE_REPUBLISHED ' || r.TABLE_NAME || ' (type change); ';
  end for;
  -- Column added or removed
  for r in c_add do
    stmt := 'alter table {{DEMO_L0}}.MAINTENANCE."' || r.TABLE_NAME || '" add column "' || r.COLUMN_NAME || '" ' || r.TYPE_SQL;
    execute immediate :stmt;
    actions := actions || 'COLUMN_ADDED ' || r.TABLE_NAME || '.' || r.COLUMN_NAME || '; ';
  end for;
  for r in c_del do
    stmt := 'alter table {{DEMO_L0}}.MAINTENANCE."' || r.TABLE_NAME || '" drop column "' || r.COLUMN_NAME || '"';
    execute immediate :stmt;
    actions := actions || 'COLUMN_REMOVED ' || r.TABLE_NAME || '.' || r.COLUMN_NAME || '; ';
  end for;
  -- New rows (columns now match on both sides)
  for r in c_rows do
    stmt := 'insert into {{DEMO_L0}}.MAINTENANCE."' || r.TABLE_NAME || '" (' || r.COLS || ') select ' || r.COLS
         || ' from {{DEMO_L0}}.PUBLISHER."' || r.TABLE_NAME || '" minus select ' || r.COLS
         || ' from {{DEMO_L0}}.MAINTENANCE."' || r.TABLE_NAME || '"';
    execute immediate :stmt;
    n := SQLROWCOUNT;
    if (n > 0) then
      actions := actions || 'ROWS_ADDED ' || r.TABLE_NAME || ' ' || n || '; ';
    end if;
  end for;
  update {{DEMO_L0}}.SYNC.L0_SYNC_STATE set LAST_SYNC_AT = current_timestamp(), LAST_ACTIONS = nullif(:actions, '');
  if (actions <> '') then
    insert into {{DEMO_L0}}.SYNC.SYNC_LOG values (current_timestamp(), :actions);
  end if;
  return iff(actions = '', 'no changes', actions);
end;
$$;

-- First sync builds MAINTENANCE from the published baseline
call {{DEMO_L0}}.SYNC.SP_SYNC_L0();

-- The "data product view" inside the CLD (shows that a view in L0 also breaks)
create or replace view {{DEMO_L0}}.MAINTENANCE.V_NOTIFICATION_EQUIPMENT as
select n.MAINTENANCENOTIFICATION, n.CREATEDON, n.DOWNTIMEHOURS, n.NOTIFICATIONTEXT, e.EQUIPMENTNAME, e.PLANT, e.FLEETTYPE
from {{DEMO_L0}}.MAINTENANCE.MAINT_NOTIFICATION n
join {{DEMO_L0}}.MAINTENANCE.EQUIPMENT e on e.EQUIPMENT = n.EQUIPMENT;

-- The sync task: serverless, every minute. Created suspended; 78_start.sql resumes it.
create or replace task {{DEMO_L0}}.SYNC.SYNC_L0
  schedule = '1 minute'
  user_task_managed_initial_warehouse_size = 'XSMALL'
  comment = 'CP11: CLD sync stand-in (PUBLISHER -> MAINTENANCE)'
as call {{DEMO_L0}}.SYNC.SP_SYNC_L0();

select count(*) || ' notifications, ' || (select count(*) from {{DEMO_L0}}.MAINTENANCE.EQUIPMENT) || ' machines in L0'
from {{DEMO_L0}}.MAINTENANCE.MAINT_NOTIFICATION;
